  protected totalChanged(detail: InvoiceDetail): void {
    this.invoices.update((list) =>
      list.map((i) =>
        i.id === detail.id
          ? {
              ...i,
              status: detail.status,
              issueDate: detail.issueDate,
              dueDate: detail.dueDate,
              total: detail.total,
            }
          : i,
      ),
    );
  }
}
